	CreateTraceAnnotation(context.Context, *CreateTraceAnnotationRequest) (*CreateTraceAnnotationResponse, error)
	// ListTraceAnnotations lists notes for a trace
	ListTraceAnnotations(context.Context, *ListTraceAnnotationsRequest) (*ListTraceAnnotationsResponse, error)
