	ListCustomColumns(context.Context, *ListCustomColumnsRequest) (*ListCustomColumnsResponse, error)
	// UpsertCustomColumn creates or updates a custom column definition.
	UpsertCustomColumn(context.Context, *UpsertCustomColumnRequest) (*UpsertCustomColumnResponse, error)
	// DeleteCustomColumn removes a custom column definition by key.
	DeleteCustomColumn(context.Context, *DeleteCustomColumnRequest) (*DeleteCustomColumnResponse, error)
