	ListTraceViews(context.Context, *ListTraceViewsRequest) (*ListTraceViewsResponse, error)
	// UpsertTraceView creates or updates a saved view.
	UpsertTraceView(context.Context, *UpsertTraceViewRequest) (*UpsertTraceViewResponse, error)
	// DeleteTraceView removes a saved view by id.
	DeleteTraceView(context.Context, *DeleteTraceViewRequest) (*DeleteTraceViewResponse, error)
